    "仅当本机登录无法用于 SoduWork 时使用。授权成功后请新建对话，已有对话保留原登录。": "SoduWork에서 이 컴퓨터의 로그인을 사용할 수 없는 경우에만 사용하세요. 인증 후 새 대화를 시작하세요. 기존 대화는 원래 로그인을 유지합니다.",
    "独立授权已完成。请新建对话使用；已有对话保留原登录。": "별도 인증이 완료되었습니다. 새 대화에서 사용하세요. 기존 대화는 원래 로그인을 유지합니다.",
    "连接未完成": "연결이 완료되지 않았습니다",
    "请检查网络和执行机状态，然后重试。": "네트워크와 실행 컴퓨터를 확인한 뒤 다시 시도하세요.",
