    "一次性设备码": "일회용 기기 코드",
    "复制设备码": "기기 코드 복사",
    "账号授权由 OpenAI 完成。SoduWork 不会显示或索取你的密码。": "계정 승인은 OpenAI가 처리합니다. SoduWork는 비밀번호를 표시하거나 요청하지 않습니다.",
    "继续登录": "로그인 계속",
