    "打开官方授权页": "공식 승인 페이지 열기",
    "取消授权": "승인 취소",
    "这台机器上的 Codex 尚不可用，请先检查安装。": "이 컴퓨터에서 Codex를 사용할 수 없습니다. 설치 상태를 먼저 확인하세요.",
    "已检测到这台机器的 Codex 登录，无需再次授权。": "이 컴퓨터의 Codex 로그인이 확인되었습니다. 다시 인증할 필요가 없습니다.",
    "执行机暂不支持此登录窗口，请更新 SoduWork 后重试。": "실행 컴퓨터가 아직 이 로그인 창을 지원하지 않습니다. SoduWork를 업데이트한 뒤 다시 시도하세요.",
    "暂时无法确认登录状态，请稍后重试。": "로그인 상태를 확인할 수 없습니다. 잠시 후 다시 시도하세요.",
    "执行机返回的授权信息不完整，请更新 SoduWork 后重试。": "실행 컴퓨터가 불완전한 승인 정보를 반환했습니다. SoduWork를 업데이트한 뒤 다시 시도하세요.",
    "暂时无法连接执行机。重试或取消前将再次确认授权状态。": "실행 컴퓨터에 연결할 수 없습니다. 재시도하거나 취소하기 전에 승인 상태를 다시 확인합니다.",
    "取消未完成，请确认执行机在线后重试取消。": "취소가 완료되지 않았습니다. 실행 컴퓨터가 온라인인지 확인하고 다시 취소하세요.",
    "设备码已复制": "기기 코드를 복사했습니다",
    "复制失败，请选中设备码后手动复制。": "복사하지 못했습니다. 기기 코드를 선택하여 직접 복사하세요.",
    "授权页已打开，完成后会自动更新。": "승인 페이지를 열었습니다. 완료하면 자동으로 업데이트됩니다.",
    "无法打开浏览器，请稍后重试。": "브라우저를 열 수 없습니다. 잠시 후 다시 시도하세요.",
    "Codex 账号": "Codex 계정",
    "优先使用这台机器已有的 Codex 登录；未登录时再由官方页面完成授权。": "이 컴퓨터의 기존 Codex 로그인을 우선 사용하고, 로그아웃 상태일 때만 공식 페이지에서 승인합니다.",
    "请在授权窗口中查看登录进度。": "승인 창에서 로그인 진행 상황을 확인하세요.",
    "登录窗口未加载，请更新 SoduWork 后重试。": "로그인 창을 불러오지 못했습니다. SoduWork를 업데이트한 뒤 다시 시도하세요.",

    "独立账号登录": "독립 계정 로그인",
    "登录 Codex": "Codex 로그인",
    "由官方 Codex 完成授权并保管登录信息。登录成功后用于新对话，已有对话保留原登录目录。": "공식 Codex가 인증 및 로그인 정보를 관리합니다. 로그인 후 새 채팅에 적용되며 기존 채팅은 원래 로그인 디렉터리를 유지합니다.",
    "等待官方登录授权": "공식 로그인 승인 대기 중",
    "登录未完成": "로그인 미완료",
    "请按下方官方地址与设备码完成登录。此操作不启动模型对话。": "아래 공식 주소와 기기 코드로 로그인하세요. 모델 대화는 시작되지 않습니다.",
    "Google Research Harness² 核心随 SoduWork 升级；首次使用点击「准备组件」准备执行组件。「重装 / 升到最新」会准备 SoduWork 支持的执行组件版本；卸载仅停用本底座，保留共享 OpenCode。": "Google Research Harness² 코어는 SoduWork와 함께 업데이트됩니다. 처음에는 구성 요소 준비를 선택하세요. 다시 설치하면 지원되는 실행 구성 요소를 준비합니다. 제거는 이 런타임만 비활성화하며 공유 OpenCode는 유지합니다.",
    "停用这台机器上的 Harness²，新任务不能再派给它；保留内置核心、共享 OpenCode 和任务记录。点「启用」可重新启用。": "이 컴퓨터의 Harness²를 비활성화하여 새 작업 배정을 중지합니다. 코어, 공유 OpenCode 및 작업 기록은 유지됩니다. 활성화를 선택하여 다시 사용할 수 있습니다.",
