    '决定任务视图窗口在桌面上占多大空间。': '이슈 보기 창이 바탕화면에서 차지할 공간을 결정합니다.',
    '只调字，不动窗口大小（用户定：两者分开设）。近视眼或高分屏可把字调大。': '창 크기는 그대로 글자 크기만 조정합니다(각각 개별 설정). 고해상도 화면에서 가독성이 좋아집니다.',
    '如 C:\\Program Files\\code': '예: C:\\Program Files\\code',
    '本机存放代码的根目录，默认已设为「用户目录\\SoduWork」，想换直接改；清空保存即恢复默认。派活给 AI 时，SoduWork 会组合根目录与工程子目录，让执行器在正确位置工作。该设置只保存在本机。': '코드를 보관하는 로컬 루트 폴더입니다. 기본값은 “사용자 폴더\\SoduWork”. 비우고 저장하면 기본값으로 복원됩니다. AI에게 작업을 맡길 때 SoduWork는 이 경로와 프로젝트 하위 폴더를 조합해 실행기가 올바른 위치에서 동작하게 합니다. 이 설정은 이 컴퓨터에만 저장됩니다.',
    '这三件都是桌面上的快捷入口，关掉只是不显示——任务、通知、团队都在这扇主窗口里照常用。 托盘图标右键也能改这几项。': '이 세 가지는 바탕화면 바로가기입니다. 꺼도 표시되지 않을 뿐, 이슈, 알림, 팀은 메인 창에서 계속 사용할 수 있습니다. 트레이 아이콘 우클릭으로도 변경할 수 있습니다.',
