    '当前操作尚未结束，权限未切换，请稍后重试': '현재 작업이 아직 끝나지 않아 권한이 전환되지 않았습니다. 잠시 후 다시 시도하세요',
    '无法确认原会话，已停止权限切换，请重新打开会话': '원본 대화를 확인할 수 없어 권한 전환을 중지했습니다. 대화를 다시 여세요',
    'Agent 未确认新权限，已保留原权限和会话进度': 'Agent가 새 권한을 확인하지 않아 원래 권한과 대화 진행을 유지했습니다',
    '当前 Agent 暂不支持在执行中恢复原会话，请先停止再切换权限': '현재 Agent는 실행 중 세션 복원을 지원하지 않습니다. 먼저 중지한 후 권한을 전환하세요',
    '当前操作的结果尚未确认，请检查结果后继续': '현재 작업의 결과가 아직 확인되지 않았습니다. 결과를 확인한 후 계속하세요',
    'Agent 未确认当前操作已结束，权限未切换': 'Agent가 작업 종료를 확인하지 않아 권한이 바뀌지 않았습니다',
    '权限切换未完成，原权限保持不变': '권한 전환이 완료되지 않았습니다. 원래 권한이 그대로 적용됩니다',
    '正在切换权限，此操作尚未执行': '권한을 전환하는 중입니다. 이 작업은 아직 실행되지 않았습니다',
    '执行机尚未确认本轮权限已生效，请重试': '실행 머신이 이번 라운드 권한 적용을 아직 확인하지 않았습니다. 다시 시도하세요',
