    '正在确认或创建对话，请稍候': '대화를 확인하거나 만드는 중입니다. 잠시만 기다려주세요',
    '会话设置已变化，请重新发送': '대화 설정이 바뀌었습니다. 메시지를 다시 보내세요',
    '上一项尚未完成，请处理后继续队列': '이전 항목이 아직 끝나지 않았습니다. 처리한 후 대기열을 계속하세요',
    '会话工具恢复超时，请重试；已有对话和文件均已保留': '대화 도구 복원이 시간 초과되었습니다. 다시 시도하세요. 기존 대화와 파일은 모두 보존되었습니다',
