    '最多 120 个字符': '최대 120자',
    '请输入会话名称': '대화 이름을 입력하세요',
    '改名暂不可用，请重新打开会话': '이름 바꾸기를 지금 쓸 수 없습니다. 대화를 다시 여세요',
    '改名未保存，请重试': '이름을 저장하지 못했습니다. 다시 시도하세요',
    '正在核对这一轮的细节，已有工作会继续保留 · 可随时停止': '이 차례의 세부를 확인하는 중입니다. 기존 작업은 유지됩니다 · 언제든 멈출 수 있어요',
    '复杂步骤仍在执行，SoduWork 正在等待真实工具结果 · 可随时停止': '복잡한 단계가 아직 실행 중입니다. SoduWork가 실제 도구 결과를 기다립니다 · 언제든 멈출 수 있어요',
    '正在把文件、运行结果和交付说明收拢到一起 · 可随时停止': '파일, 실행 결과, 전달 설명을 모으는 중입니다 · 언제든 멈출 수 있어요',
    '这一轮还没有结束，形成可交付结果后会立即告诉你 · 可随时停止': '이 차례는 아직 끝나지 않았습니다. 전달 가능한 결과가 되면 바로 알려드릴게요 · 언제든 멈출 수 있어요',
    '正在完成必要的检查，暂时不需要你反复操作 · 可随时停止': '필요한 점검을 진행하는 중입니다. 반복 조작이 필요하지 않아요 · 언제든 멈출 수 있어요',
    '任务仍在稳步推进，完成后会把结果和依据一起交付 · 可随时停止': '작업이 착실히 진행 중입니다. 완료되면 결과와 근거를 함께 전달합니다 · 언제든 멈출 수 있어요',
    '正在处理较耗时的步骤，当前现场与上下文都已保留 · 可随时停止': '시간이 걸리는 단계를 처리하는 중입니다. 현재 상태와 컨텍스트가 모두 보존되어 있어요 · 언제든 멈출 수 있어요',
    '正在复核关键结果，避免把未验证的内容交到你手里 · 可随时停止': '핵심 결과를 다시 확인하는 중입니다. 검증되지 않은 내용이 전달되지 않게 합니다 · 언제든 멈출 수 있어요',
    '可以先喝口水，SoduWork 会继续守着这轮工作，有结果马上回来': '잠시 물 한 잔 하고 오세요. SoduWork가 이 작업을 계속 지켜보다가 결과가 나오면 바로 돌아옵니다',
    '复杂工作值得多一点耐心，愿你今天接下来的事情都顺利从容': '복잡한 작업에는 조금 더 인내가 필요합니다. 오늘 남은 일이 모두 순탄하길 바랍니다',
    '正在把最后几处细节讲清楚，感谢你的耐心等待 · 可随时停止': '마지막 세부를 명확히 하고 있습니다. 기다려 주셔서 감사합니다 · 언제든 멈출 수 있어요',
    '这一步需要一些时间，愿接下来的每一步都清晰、可靠、顺利': '이 단계는 시간이 조금 걸립니다. 앞으로의 한 걸음마다 명확하고 믿음직하고 순조롭길 바랍니다',
    '每一次高质量交付，都会成为团队下一次工作时可复用的经验': '품질 높은 전달이 생길 때마다 팀이 다음에 재사용할 경험이 됩니다',
    '让个人经验成为团队能力，让成熟的工作方法在企业中持续复用': '개인 경험을 팀 역량으로 만들고, 검증된 작업 방식을 기업에서 계속 재사용합니다',
    '计划已经形成，正在完成实现与运行验证…': '계획이 세워졌고, 구현과 실행 검증을 마무리하는 중…',
    '复核发现交付缺口，正在自动补齐并重新验证…': '재확인에서 전달 공백이 발견되어 자동으로 채우고 다시 검증하는 중…',
    '正在做交付复核，并补齐最后的缺口…': '전달 재확인과 마지막 공백을 채우는 중…',
