    '先查看工作区和现有内容，确认基础情况。': '먼저 작업 공간과 기존 내용을 확인해 기초를 파악합니다.',
    '目标和输入已确认，开始形成可交付内容。': '목표와 입력을 확정하고 전달물을 만들기 시작합니다.',
    '已开始执行，正在准备工作环境并确认现状。': '실행을 시작했습니다. 환경을 준비하고 현재 상태를 확인하는 중입니다.',
