    '模型与执行底座独立保存，每次自动化运行使用这里的选择': '모델은 실행 기반과 별도로 저장되며 매번 여기서 선택한 모델을 사용합니다',
    '保存的是执行底座类型；每次运行会在当前设备选择可用席位': '저장되는 것은 실행 기반 유형입니다. 실행 때마다 현재 기기에서 쓸 수 있는 자리를 고릅니다',
    '请打开 Agent 管理，确认 Runner 已启动并已连接当前环境': 'Agent 관리를 열어 Runner가 시작되고 현재 환경에 연결됐는지 확인하세요',
