    '描述要自动完成的工作和执行时间，发送后确认配置。': '자동으로 할 작업과 실행 시간을 적고, 보낸 뒤 구성을 확인합니다.',
    '对话暂时没有打开，请重试；也可以选择手动配置。': '대화가 아직 열리지 않았습니다. 다시 시도하거나 수동 구성을 선택하세요.',
