    '当前范围还没有可用于自动化的企业插件，请先由管理员审核并绑定。': '현재 범위에는 자동화에 쓸 기업 플러그인이 아직 없습니다. 먼저 관리자가 검토하고 연결해야 합니다.',
    '你自己的个人插件在「直接执行 → 工作方法」里选用。': '본인의 개인 플러그인은 “직접 실행 → 작업 방식”에서 고릅니다.',
