    '这台机器上还没有能接活的智能体。装一个 CLI（OpenCode / Claude Code / Pi），或让管理员把执行底座配好。': '이 컴퓨터에는 아직 일을 받을 Agent가 없어요. CLI(OpenCode / Claude Code / Pi)를 깔거나 관리자에게 실행 기반 구성을 요청하세요.',
    '填错的话这一环起不来（网关不提供模型列表，SoduWork 没法先替你核对）。常用的让管理员加进「模型服务」的开放清单，以后直接点就行。': '잘못 적으면 이 단계가 안 떠요(게이트웨이가 모델 목록을 주지 않아 SoduWork가 먼저 확인하지 못함). 자주 쓰는 것은 관리자에게 “모델 서비스” 허용 목록에 넣어 달라 하면 나중엔 바로 누르면 됩니다.',
    '不换人时按上一环那位算：它要是用自己模型的（Claude Code、托管的 AI），这里选了也不生效。': '사람을 안 바꾸면 앞 단계의 설정대로예요. 자기 모델을 쓰는(Claude Code, 관리형 AI 등) 경우 여기서 골라도 효과가 없어요.',
