    'OpenAI 官方 CLI。用它自己的账号（ChatGPT 登录或 OpenAI key），不吃 SoduWork 这边的模型配置。': 'OpenAI 공식 CLI입니다. 자체 계정(ChatGPT 로그인 또는 OpenAI 키)을 사용하며 SoduWork 모델 설정은 사용하지 않습니다.',
