    'MIT 开源的 DeepSeek 官方 Agent 框架（dsh）；通过 ACP 接入，支持公司 OpenAI 兼容模型或个人 DeepSeek Key。': 'MIT 라이선스의 공식 DeepSeek Agent 프레임워크(dsh)입니다. ACP로 연결하고 회사 OpenAI 호환 모델 또는 개인 DeepSeek 키를 지원합니다.',
