    '按 SoduWork 权限、需求和验收协议完成适配': 'SoduWork 권한, Issue, 검수 요건에 맞춰 조정했어요',
    '插件已从你的日常对话工具箱移除，企业需求和自动化不受影响': '플러그인을 평소 대화 도구함에서 뺐어요. 기업 Issue와 자동화는 영향 없어요',
    '本机保存的所有版本都会移除，之后的对话和需求不能再调用它。已经上传到企业、正在运行的需求与历史记录不会受影响。': '로컬에 저장한 모든 버전이 지워지고 이후 대화와 Issue에서 호출할 수 없어요. 기업에 올린 것, 실행 중인 Issue, 기록은 영향이 없습니다.',
    '正在运行的需求、历史对话和已经上传企业的版本都保持原快照。': '실행 중인 Issue, 대화 기록, 기업에 올린 버전은 원래 스냅샷 그대로예요.',
    '按需求完成标准验收本次交付': 'Issue 완료 기준으로 이번 전달 검수',
    '成果已验收，需求完成并保留全过程证据': '산출물을 검수했고 Issue가 끝났으며 전 과정 증거를 남겼어요',
    '基于当前版本创建新的不可变版本；旧版本和既有需求记录保持不变。': '지금 버전을 밑으로 새 불변 버전을 만들어요. 이전 버전과 기존 Issue 기록은 그대로입니다.',
    '选择团队已开放的方法，执行需求时会随节点一起加载': '팀이 연 방식을 고르면 Issue 실행 때 노드와 함께 실려요',
    '调用入口 · 需求输入 · 安装设置': '부르는 입구 · Issue 입력 · 설치 설정',
    '需求公开参数': 'Issue 공개 매개변수',
    '启动需求或自动化时填写，不用于收集账号和密钥': 'Issue나 자동화를 시작할 때 채우며 계정이나 키를 모으는 데 쓰지 않아요',
