    '受控需求专用': '통제되는 Issue 전용',
    '管理员没有开放个人对话安装；请从需求或自动化按企业绑定使用。': '관리자가 개인 대화 설치를 열어 주지 않았어요. Issue나 자동화에서 기업 연결로 쓰세요.',
    '在“新建”或任意对话中输入 /{arg2835}，即可让本轮采用该插件的方法和质量标准；上传企业并审核发布后，才会开放需求与自动化入口。': '“새로 만들기”나 아무 대화에서 /{arg2835}을(를) 치면 이번 차례에 그 플러그인의 방식과 품질 기준을 씁니다. 기업에 올려 검토·발표된 뒤에야 Issue와 자동화 입구가 열려요.',
    '在“新建”或任意对话中输入 /{arg2836}，即可让本轮采用该插件的方法和质量标准；完整审批与发布仍从需求启动。': '“새로 만들기”나 아무 대화에서 /{arg2836}을(를) 치면 이번 차례에 그 플러그인의 방식과 품질 기준을 씁니다. 본격 승인과 배포는 여전히 Issue에서 시작해요.',
