    '直接对话；需要持续推进时设为目标，需要协作时创建需求。': '바로 대화해요. 계속 밀고 가려면 목표로, 같이 하려면 Issue를 만드세요.',
    '需求已创建，但协作会话未建立，可在需求详情里重试': 'Issue는 만들었지만 협업 대화가 맺어지지 않았어요. Issue 세부에서 다시 시도할 수 있어요',
    '需求已创建，但协作会话未建立：{arg581}': 'Issue는 만들었지만 협업 대화가 맺어지지 않았어요: {arg581}',
    '执行选项没有加载成功；仍可仅创建需求，修改内容或工程后会自动重试。': '실행 옵션을 못 불러왔어요. Issue만 만들 수 있고 내용이나 저장소를 바꾸면 자동으로 다시 시도해요.',
