    '需求进入需求中心，不会自动启动 Agent。': 'Issue는 Issue 센터로 들어가고 Agent는 자동으로 안 켜져요.',
    '需求尚未同步到服务端': 'Issue가 아직 서버에 동기화되지 않았어요',
    '需求建好了，但没交出去（{arg824}），可以在详情里重派': 'Issue는 만들었지만 맡기지 못했어요({arg824}). 세부에서 다시 맡길 수 있어요',
    '需求建好了，但没交出去（派活失败），可以在详情里重派': 'Issue는 만들었지만 맡기기에 실패했어요. 세부에서 다시 맡길 수 있어요',
    '需求名不能空哦': 'Issue 이름은 비우면 안 돼요',
    '这位同事当前不可接收需求，请刷新后重新选择': '이 동료는 지금 Issue를 못 받아요. 새로 고치고 다시 고르세요',
    '需求没有保存成功，内容还在表单里，请再试一次': 'Issue를 저장하지 못했어요. 내용은 양식에 그대로 있으니 다시 시도하세요',
    '需求已建，附件上传失败：文件太大': 'Issue를 만들었지만 첨부 올리기 실패: 파일이 너무 커요',
    '需求已建，附件上传失败，可到详情重试': 'Issue를 만들었지만 첨부 올리기에 실패했어요. 세부에서 다시 시도할 수 있어요',
