    '文件夹为空': '이 폴더는 비었어요',
    '返回资料库根目录后可新建内容，再移动到其他文件夹。': '자료 보관함 맨 위로 돌아가면 새로 만들고 다른 폴더로 옮길 수 있어요.',
    '创建你的第一张图像': '첫 그림 만들기',
    '你使用 SoduWork 创建的图像会显示在这里。': 'SoduWork로 만든 그림이 여기 나타나요.',
    '创建图像': '그림 만들기',
    '你使用 SoduWork 创建的内容（如图像和文档）会显示在这里。': 'SoduWork로 만든 것(그림, 문서 등)이 여기 나타나요.',
    '开始创建': '만들기 시작',
    '请围绕资料《{name}》展开对话。': '자료 “{name}”을(를) 두고 대화해 주세요.',
    '用户从资料库选择了这份文件，请使用实际可读取的附件回答；如果附件不可读取，请明确说明。': '사용자가 자료 보관함에서 이 파일을 골랐어요. 실제로 읽을 수 있는 첨부로 답하고, 읽을 수 없으면 분명히 말해 주세요.',
    '请帮我创建一张图像。请先询问我想要的主题、风格、尺寸和用途，然后开始创作。完成后提醒我可以将成果保存到资料库。': '그림 하나 만들어 주세요. 먼저 원하는 주제, 느낌, 크기, 쓰임을 물어보고 만들기 시작하세요. 끝나면 산출을 자료 보관함에 저장할 수 있다고 알려 주세요.',
    '请帮我创建一份文档。请先询问文档主题、结构、语气和格式，然后开始撰写。完成后提醒我可以将成果保存到资料库。': '문서 하나 만들어 주세요. 먼저 주제, 구성, 어조, 형식을 물어보고 쓰기 시작하세요. 끝나면 산출을 자료 보관함에 저장할 수 있다고 알려 주세요.',
    '请帮我创建一份电子表格。请先询问数据字段、计算规则和展示方式，然后开始制作。完成后提醒我可以将成果保存到资料库。': '표 계산 하나 만들어 주세요. 먼저 자료 칸, 계산 규칙, 보여 주는 방식을 물어보고 만들기 시작하세요. 끝나면 산출을 자료 보관함에 저장할 수 있다고 알려 주세요.',
    '请帮我创建一份演示文稿。请先询问主题、受众、页数和风格，然后开始制作。完成后提醒我可以将成果保存到资料库。': '발표 자료 하나 만들어 주세요. 먼저 주제, 청중, 장수, 느낌을 물어보고 만들기 시작하세요. 끝나면 산출을 자료 보관함에 저장할 수 있다고 알려 주세요.',
    '用户从资料库点击了“{kind}”新建入口，请按用户需求完成创作，并提醒用户可将成果保存到资料库。': '사용자가 자료 보관함에서 “{kind}” 새로 만들기를 골랐어요. 사용자 요구에 맞춰 만들고 산출을 자료 보관함에 저장할 수 있다고 알려 주세요.',
    '存储位置仅支持 local 或 minio': '저장 위치는 local이나 minio만 받아요',
    '收藏状态必须为布尔值': '즐겨찾기 상태는 참/거짓 값이어야 해요',
