    '分享文件': '파일 공유',
    '分享失败，请重试': '공유에 실패했습니다. 다시 시도해 주세요.',
    '对话面板暂时不可用': '대화 패널을 지금 사용할 수 없습니다',
    '会话成果': '채팅 산출물',
    '云端成果': '클라우드 산출물',
    '已收藏': '즐겨찾기',
    '已隐藏': '숨김',
    '已修改': '수정됨',
    '对话入口尚未就绪，请稍后重试；也可以选择手动录入。': '대화 진입점이 아직 준비되지 않았습니다. 잠시 후 다시 시도하거나 직접 입력해 주세요.',
    '请在对话中描述需求，发送后确认标题、背景和完成标准。': '대화에서 이슈를 설명하고, 전송 후 제목·배경·완료 기준을 확인해 주세요.',
    '对话暂时没有打开，请重试；也可以选择手动录入。': '대화를 열지 못했습니다. 다시 시도하거나 직접 입력해 주세요.',
    '当前客户端不支持提交验收，请更新后重试。': '이 클라이언트는 아직 검수 제출을 지원하지 않습니다. 클라이언트를 업데이트한 후 다시 시도해 주세요.',
    '当前客户端不支持验收，请更新后重试。': '이 클라이언트는 아직 검수를 지원하지 않습니다. 클라이언트를 업데이트한 후 다시 시도해 주세요.',
    '当前组织没有可分享的其他成员': '이 조직에 공유할 수 있는 다른 멤버가 없습니다',
    '文件已分享，成员会收到通知': '파일을 공유했습니다. 멤버에게 알림이 전송됩니다',
    '文件已保存': '파일을 저장했습니다',
    '执行会话在另一台设备上；在这条需求的详情里核对证据并确认即可。': '실행 대화는 다른 기기에 있습니다. 이슈 세부 정보의 검수 카드에서 증거를 확인하고 승인하세요.',
    '打开需求失败：{value1}': '이슈를 열지 못했습니다: {value1}',
    '移动到…': '이동…',
    '未选择需求': '선택된 이슈 없음',
    '搜索连接器、系统或服务': '커넥터·시스템 또는 서비스 검색',
    '公司还没有发布可用连接': '아직 공개된 회사 커넥터가 없습니다',
    '从可信模板开始，或接入一个已知的 HTTP 连接地址。': '신뢰할 수 있는 템플릿으로 시작하거나 알려진 HTTP 연결 주소를 연결하세요.',
    '公司尚未开放连接执行能力。': '회사에서 아직 커넥터 실행이 활성화되지 않았습니다.',
    '全部执行席位 · 点击需求打开 AI 工作详情': '전체 Agent 시트 · 이슈를 클릭하면 AI 작업 세부 정보가 열립니다',
    '切换到全部席位查看其他需求，或从需求池中安排新的工作。': '전체 Agent 시트로 전환하면 다른 이슈를 볼 수 있고, 이슈 풀에서 새 작업을 배정할 수 있습니다.',
    '按需求状态筛选': '이슈 상태로 필터링',
    '你可以先配置连接；管理员开放工具后，任务才会调用。': '연결은 미리 구성할 수 있습니다. 작업 호출은 관리자가 도구를 개방한 후에 가능합니다.',
    '加快安装文件校验，将旧版本清理移到后台，减少更新完成前的等待。': '설치 파일 검증을 빠르게 하고 이전 버전 정리를 백그라운드로 옮겨 업데이트 완료 전 대기 시간을 줄였습니다.',
    '完善更新状态上报的超时与进度合并，避免网络响应拖住升级流程。': '업데이트 상태 보고의 타임아웃과 진행률 병합을 개선해 네트워크 응답이 업그레이드 흐름을 막지 않도록 했습니다.',
    '修复更新期间启动入口短暂不可用的问题，文件被占用或更新中断时保留原有入口。': '업데이트 중 실행 진입점이 잠시 사용 불가능하던 문제를 수정했습니다. 파일이 사용 중이거나 업데이트가 중단되어도 기존 진입점을 유지합니다.',
    '整理插件、连接器、MCP、技能和市场页面，统一字号、卡片与操作位置，保留原有彩色图标。': '플러그인·커넥터·MCP·스킬·마켓 페이지를 정리하고 글자 크기·카드·작업 위치를 통일했으며 기존 컬러 아이콘은 유지했습니다.',
    '保留我的申请入口，简化各页添加菜单，常用连接模板默认收起并支持搜索展开。': '내 제출 내역 입구를 유지하고 각 페이지의 추가 메뉴를 단순화했습니다. 자주 쓰는 연결 템플릿은 기본 접힘, 검색으로 펼칩니다.',
    '修复工具超时后仍占用会话、继续和引导无法推进的问题；确认执行退出后再继续下一轮。': '도구가 타임아웃 후에도 세션을 점유해 계속·가이드가 진행되지 않던 문제를 수정했습니다. 실행이 종료된 후 다음 라운드를 계속합니다.',
    '补齐工具执行时限，取消当前操作时保护已有后台任务与其他请求。': '도구 실행 시간 제한을 보완하고 현재 작업을 취소할 때 기존 백그라운드 작업과 다른 요청을 보호합니다.',
    '升级改用紧凑的单一进度窗口，按实际解包和校验进度展示百分比。': '업그레이드는 컴팩트한 단일 진행 창으로 전환되어 실제 언팩·검증 진행률을 퍼센트로 표시합니다.',
    '优化安装校验与旧版本整理效率，保留已有会话、文件及回退能力。': '설치 검증과 이전 버전 정리 효율을 개선하며 기존 세션·파일·되돌리기 기능을 유지합니다.',
    '更新时显示下载、校验及安装阶段，支持等待工作结束后重启；升级过程中再次打开 SoduWork 会等待安装完成。': '업데이트 시 다운로드·검증·설치 단계를 표시하고 작업이 끝난 후 재시작을 지원합니다. 업그레이드 중에 SoduWork를 다시 열면 설치 완료를 기다립니다.',
    '修复引导消息遗漏或重复、技能未随消息发送等问题，增强对话恢复与模型页面加载的稳定性。': '가이드 메시지 누락·중복, 스킬이 메시지와 함께 전송되지 않는 문제를 수정하고 세션 복원과 모델 페이지 로딩 안정성을 강화했습니다.',
    '优化插件安装、窗口菜单、窄屏对话栏和文件预览，改善主题配色与界面可读性。': '플러그인 설치·창 메뉴·좁은 화면 대화 바·파일 미리보기를 개선하고 테마 색상과 가독성을 높였습니다.',
    '完善电脑操作时的桌面提示，并缩小 AI 团队顶部的智能体卡片。': 'PC 작업 중 데스크톱 알림을 개선하고 AI 팀 상단의 Agent 카드를 축소했습니다.',
    '打开对话失败：{value1}': '대화를 열지 못했습니다: {value1}',
    '已设为 {value1} · 派活时会拼上工程子目录告诉 AI': '{value1}에 설정됨 · 작업 지시 시 프로젝트 하위 디렉터리를 붙여 AI에 알려줍니다',
    '· 已归档 · {value1} 条': '· 보관됨 · {value1}건',
