    '已识别为本地连接器，请从可信模板接入': '로컬 커넥터로 인식되었습니다. 신뢰할 수 있는 템플릿에서 연결하세요.',
    '已识别地址与 HTTP 方式；密钥仅保留在本机配置中': '주소와 HTTP 방식을 인식했습니다. 시크릿은 로컬 구성에만 저장됩니다',
