    '执行配置在创建云端会话时确定': '실행 설정은 클라우드 세션 생성 시 고정됩니다',
    '退出后，这台电脑需要重新登录才能使用 SoduWork。确定退出？': '사인아웃하면 이 컴퓨터에서 SoduWork를 쓰려면 다시 로그인해야 해요. 사인아웃할까요?',
    '当前会话在云端执行，执行机：{arg106}': '이 대화는 클라우드에서 실행 중이에요. 실행 머신: {arg106}',
    '当前会话在云端执行，执行机由系统自动选择': '이 대화는 클라우드에서 실행 중이에요. 실행 머신은 체계가 자동으로 골라요',
    '会话由远程服务器执行。当前后台在本机，请保持本机后台在线。': '대화는 원격 서버에서 실행돼요. 지금 백그라운드는 이 기기에 있으니 온라인을 유지해 주세요.',
    'SoduWork 已自动安排远程服务器执行。': 'SoduWork가 원격 서버 실행을 자동으로 정했어요.',
    '继续在当前对话中发送消息和查看成果。执行位置保持在云端，权限由云端环境管理。': '이 대화에서 계속 메시지를 보내고 결과를 볼 수 있어요. 실행 위치는 클라우드에 남고 권한은 클라우드 환경이 관리해요.',
    '点击在右侧打开': '누르면 오른쪽에서 열어요',
    '成果文件尚未准备好': '결과 파일이 아직 준비 안 됐어요',
    '成果集同步失败': '결과 묶음 맞추기 실패',
