    '无法打开本机成果': '이 기기 결과를 열 수 없어요',
    '云端成果尚未准备好': '클라우드 결과가 아직 준비 안 됐어요',
    '账号或服务已切换，请重新打开云端环境': '계정이나 서비스가 바뀌었어요. 클라우드 환경을 다시 여세요',
    '环境已保存，但没有拿到一次性接入凭据，请重新生成': '환경은 저장했지만 한 번 쓰는 연결 자격 증명을 못 받았어요. 다시 만드세요',
    '仅显示一次': '한 번만 보여요',
    '请在这台云端电脑上完成接入。凭据不会保存到客户端，关闭窗口后无法再次查看。': '이 클라우드 컴퓨터에서 연결을 끝내세요. 자격 증명은 클라이언트에 저장되지 않고 창을 닫으면 다시 볼 수 없어요.',
    '复制凭据': '자격 증명 복사',
    '凭据拥有这台执行机的接入权限，请只在目标电脑的终端中使用，不要发到公开聊天或工单。': '이 자격 증명은 이 실행 머신에 연결할 권한이 있어요. 맞은 컴퓨터의 터미널에서만 쓰고 공개 대화나 티켓에 보내지 마세요.',
