    '账号密码': '계정 암호',
    '登录密码': '로그인 암호',
    '只保存在本机安全存储中': '이 기기의 안전 저장소에만 보관해요',
    '私钥口令（可选）': '개인키 암호구(선택)',
    '凭据只在当前客户端加密保存，不会上传到 SoduWork 服务，也不会出现在日志或会话内容中。连接测试通过后才会保存；首次成功连接会记录 SSH 主机指纹，后续连接会校验它。登录账号需要具备安装 Runner 的权限（root，或可以无交互执行 sudo）。': '자격 증명은 지금 클라이언트에 암호화해 저장하고 SoduWork 서비스로 올리지 않으며 로그나 대화 내용에도 나오지 않아요. 연결 검사를 통과해야 저장되고, 처음 연결에 성공하면 SSH 호스트 지문을 적어 둔 뒤 이후 연결에서 확인해요. 로그인 계정은 Runner를 설치할 권한(root, 또는 묻지 않고 sudo를 실행할 수 있어야 함)이 필요해요.',
    '已完成连接': '연결이 끝났어요',
    '云端电脑已接入': '클라우드 컴퓨터를 연결했어요',
    '正在刷新执行机状态…': '실행 머신 상태를 새로 하는 중…',
    '复制安装命令': '설치 명령 복사',
    '需要手动完成': '직접 끝내야 해요',
    'SoduWork 已通过 SSH 完成 Runner 安装，稍后会自动检测在线状态。': 'SoduWork가 SSH로 Runner 설치를 끝냈고, 온라인 상태는 잠시 뒤 자동으로 살펴봐요.',
    '请在目标电脑终端执行下方命令，完成后回到这里检查连接。': '맞은 컴퓨터 터미널에서 아래 명령을 실행하고, 끝나면 여기로 돌아와 연결을 확인하세요.',
    '无法复制，请手动选中命令复制': '복사가 안 됐어요. 명령을 직접 고른 뒤 복사하세요',
    '尚未连接，请确认 Runner 已启动并能访问 SoduWork 服务': '아직 연결 안 됐어요. Runner가 켜져 있고 SoduWork 서비스에 닿을 수 있는지 확인하세요',
    '当前客户端不支持云端电脑连接，请升级后重试': '이 클라이언트는 클라우드 컴퓨터 연결을 아직 지원하지 않아요. 업데이트 후 다시 시도하세요',
    '无法连接云端电脑，请检查地址、端口和登录信息': '클라우드 컴퓨터에 연결 못 했어요. 주소, 포트, 로그인 정보를 확인하세요',
    '已创建环境，但 Runner 安装失败': '환경을 만들었지만 Runner 설치가 실패했어요',
    '环境名称': '환경 이름',
    '工作目录（可选）': '작업 디렉터리(선택)',
    '留空使用执行机默认目录': '비워 두면 실행 머신 기본 폴더를 써요',
    '填写目标电脑可以访问的 SoduWork 服务地址。工作目录必须是目标电脑上的绝对路径。': '맞은 컴퓨터가 닿을 수 있는 SoduWork 서비스 주소를 적으세요. 작업 디렉터리는 맞은 컴퓨터 안의 절대 경로여야 해요.',
    '会先测试 SSH 连接，再创建环境并自动安装 Runner；不需要复制命令到另一台窗口。': '먼저 SSH 연결을 검사한 뒤 환경을 만들고 Runner를 자동으로 깔아요. 명령을 다른 창에 복사할 필요가 없어요.',
    '确认移除这台专属执行机？': '이 전용 실행 머신을 없앨까요?',
    '空闲连接会立即断开并从当前账号移除。目标电脑上的文件不会被删除；仍在执行的会话需要先完成。': '쉬고 있는 연결은 곧 끊기고 지금 계정에서 없어져요. 맞은 컴퓨터의 파일은 지우지 않고, 아직 도는 대화는 먼저 끝내야 해요.',
    '自动接收': '자동 받기',
    '暂停新会话': '새 대화 잠깐 멈추기',
    '暂停接收只影响新会话，已有会话继续执行。工作目录：': '받기 멈춤은 새 대화에만 영향을 주고 있는 대화는 계속 돌아가요. 작업 디렉터리:',
    '。更换目录可通过“更新 Runner 密钥”重新生成接入命令。': '. 폴더를 바꾸려면 "Runner 키 새로 하기"로 연결 명령을 다시 만들 수 있어요.',
    '更换设备时可从当前账号移除这台执行机。': '기기를 바꿀 때 이 실행 머신을 지금 계정에서 없앨 수 있어요.',
    '移除环境': '환경 없애기',
    '请先停止目标电脑上的 Runner，并确认没有运行中的会话。生成后旧密钥立即失效，在目标电脑重新执行接入命令即可恢复连接。': '먼저 맞은 컴퓨터의 Runner를 멈추고 도는 대화가 없는지 확인하세요. 만들면 예전 키는 곧 무효가 되고, 맞은 컴퓨터에서 연결 명령을 다시 실행하면 이어요.',
    '留空使用当前服务地址': '비워 두면 지금 서비스 주소를 써요',
    '新目录会写入接入命令，在目标电脑执行后生效。已有文件会保留在原目录。': '새 폴더는 연결 명령에 적혀 맞은 컴퓨터에서 실행하면 적용돼요. 있는 파일은 원래 폴더에 남아요.',
    '完整凭据只显示这一次，关闭窗口后无法恢复。': '온전한 자격 증명은 이 한 번만 보여요. 창을 닫으면 되살릴 수 없어요.',
    '请在目标电脑上安装 Node.js 22.19 或更新版本，然后执行：': '맞은 컴퓨터에 Node.js 22.19 또는 더 새 버전을 깔고 나서 실행하세요:',
    '安装完成后重启 Runner，系统会自动重新检测 Agent。': '설치가 끝나면 Runner를 다시 시작하고, 체계가 Agent를 자동으로 다시 살펴봐요.',
    '云端执行方式': '클라우드 실행 방식',
    '本机技能、插件和目标模式请在本地使用；云端使用服务器已配置的能力': '이 기기 Skill, 플러그인과 목표 방식은 로컬에서 쓰고, 클라우드는 서버에 정해 둔 능력을 써요',
    '当前 Agent 没有可用的云端执行机，请在“云端环境”中配置或更换 Agent': '지금 Agent는 쓸 수 있는 클라우드 실행 머신이 없어요. "클라우드 환경"에서 정하거나 Agent를 바꾸세요',
    '请选择可用模型': '쓸 수 있는 모델을 고르세요',
    '请更新客户端后创建云端会话': '클라이언트를 새로 하고 나서 클라우드 대화를 만드세요',
    '云端会话没有创建成功，原消息已保留': '클라우드 대화를 못 만들었고 원래 메시지는 남았어요',
    '云端已接收，请从历史会话重新打开；再次点击也不会重复发送': '클라우드가 받았어요. 지난 대화에서 다시 열고, 또 눌러도 겹쳐 보내지 않아요',
    '「{arg834}」可能来自企业微信临时缓存，已无法读取，请另存后拖入': '"{arg834}"은(는) 회사 위챗 임시 저장에서 온 것 같아 읽을 수 없어요. 따로 저장한 뒤 끌어오세요',
